-- .61 行业库 n_industry 的美业表（TDD-美业域迁移新库 B-6）。由 gen.py 从美业测试的 db/n_industry V1、V2 生成，不要手改。
-- 只在这些表都为空时执行（run.sh 先核对行数并备份）：已有的先删，按定稿结构建 12 张。
-- 与餐饮共用的 ind_assignment 不在这里，见 03-alter-shared-table.sql；触发器见 04-triggers.sql。

DROP TABLE IF EXISTS `bty_work_order`;
CREATE TABLE `bty_work_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '物理自增主键，不对外',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT '沿当前租户上下文；不另启租户体系',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '商家主体范围；不等于租户',
  `created_at` datetime(3) NOT NULL COMMENT '创建时刻',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际操作者业务引用',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新操作者',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '沿BaseEntity；事实表禁止删除或软删覆盖',
  `work_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '工单号',
  `store_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '门店',
  `appointment_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '来源预约',
  `customer_ref` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '可信客户',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'OPEN等',
  `scope_revision` bigint NOT NULL COMMENT '服务范围版本',
  `scope_frozen` tinyint NOT NULL COMMENT '关闭检查冻结',
  `started_at` datetime(3) DEFAULT NULL COMMENT '实际开始',
  `finished_at` datetime(3) DEFAULT NULL COMMENT '范围完工',
  `closed_at` datetime(3) DEFAULT NULL COMMENT '关闭',
  `identity_kind` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'identity_kind',
  `identity_ref` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'identity_ref',
  `source_reception_operation_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'source_reception_operation_no',
  `appointment_arrangement_revision` bigint DEFAULT NULL COMMENT 'appointment_arrangement_revision',
  `frozen_scope` json DEFAULT NULL COMMENT 'frozen_scope',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_work_order_1` (`tenant_no`,`entity_no`,`work_order_no`),
  UNIQUE KEY `uk_bty_work_order_2` (`tenant_no`,`entity_no`,`appointment_no`),
  KEY `idx_bty_work_order_1` (`tenant_no`,`entity_no`,`store_no`,`status`,`created_at`),
  CONSTRAINT `ck_bty_work_order_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_bty_work_order_2` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `ck_bty_work_order_3` CHECK ((`scope_revision` >= 0)),
  CONSTRAINT `ck_bty_work_order_4` CHECK (((`finished_at` is null) or ((`started_at` is not null) and (`finished_at` >= `started_at`)))),
  CONSTRAINT `ck_bty_work_order_5` CHECK ((`scope_frozen` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='并入原工单上下文 bty_work_order_context（一对一）；服务工单';

DROP TABLE IF EXISTS `bty_service_task`;
CREATE TABLE `bty_service_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '物理自增主键，不对外',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT '沿当前租户上下文；不另启租户体系',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '商家主体范围；不等于租户',
  `created_at` datetime(3) NOT NULL COMMENT '创建时刻',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际操作者业务引用',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新操作者',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '沿BaseEntity；事实表禁止删除或软删覆盖',
  `task_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '任务号',
  `work_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '工单',
  `scope_revision` bigint NOT NULL COMMENT '创建范围版本',
  `sku_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '规格',
  `definition_version_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '规则',
  `appointment_item_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '预约项目行',
  `qty` decimal(18,6) NOT NULL COMMENT '承诺数量',
  `done_qty` decimal(18,6) NOT NULL COMMENT '已做',
  `voided_qty` decimal(18,6) NOT NULL COMMENT '合法未做撤销',
  `uom` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'PENDING等',
  `binding_revision` bigint NOT NULL COMMENT '当前来源绑定版本指针',
  `started_at` datetime(3) DEFAULT NULL COMMENT '开始',
  `finished_at` datetime(3) DEFAULT NULL COMMENT '完工',
  `execution_snapshot` json NOT NULL COMMENT '冻结执行内容',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_service_task_1` (`tenant_no`,`entity_no`,`task_no`),
  KEY `idx_bty_service_task_1` (`tenant_no`,`entity_no`,`work_order_no`,`status`),
  KEY `idx_bty_service_task_2` (`tenant_no`,`entity_no`,`status`,`updated_at`),
  CONSTRAINT `ck_bty_service_task_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_bty_service_task_2` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `ck_bty_service_task_3` CHECK ((`qty` > 0)),
  CONSTRAINT `ck_bty_service_task_4` CHECK ((`done_qty` >= 0)),
  CONSTRAINT `ck_bty_service_task_5` CHECK ((`voided_qty` >= 0)),
  CONSTRAINT `ck_bty_service_task_6` CHECK ((`scope_revision` >= 0)),
  CONSTRAINT `ck_bty_service_task_7` CHECK ((`binding_revision` >= 0)),
  CONSTRAINT `ck_bty_service_task_8` CHECK (((`done_qty` + `voided_qty`) <= `qty`)),
  CONSTRAINT `ck_bty_service_task_9` CHECK (((`finished_at` is null) or ((`started_at` is not null) and (`finished_at` >= `started_at`))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='可独立执行服务任务';

DROP TABLE IF EXISTS `bty_service_step`;
CREATE TABLE `bty_service_step` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键，自增',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '租户号',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '所属主体编号',
  `step_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '步骤编号',
  `task_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '所属服务任务编号（一个项目的执行）',
  `step_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '服务模板里的稳定步骤码（洗、剪、染、吹）',
  `sequence_no` int NOT NULL COMMENT '步骤顺序',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '状态：PENDING 待开始、IN_PROGRESS 进行中、DONE 完成、SKIPPED 跳过',
  `started_at` datetime(3) DEFAULT NULL COMMENT '开始时间',
  `finished_at` datetime(3) DEFAULT NULL COMMENT '结束时间',
  `result_snapshot` json DEFAULT NULL COMMENT '非敏感的执行结果（如色号、时长）',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0 = 正常，1 = 已删除',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本号，每次修改加 1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `created_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间，每次修改自动更新',
  `updated_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_service_step_1` (`tenant_no`,`entity_no`,`step_no`),
  UNIQUE KEY `uk_bty_service_step_2` (`tenant_no`,`entity_no`,`task_no`,`step_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='服务步骤：一个项目的分步进度（洗、剪、染、吹）';

DROP TABLE IF EXISTS `bty_trade_binding`;
CREATE TABLE `bty_trade_binding` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '物理自增主键，不对外',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT '沿当前租户上下文；不另启租户体系',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '商家主体范围；不等于租户',
  `created_at` datetime(3) NOT NULL COMMENT '创建时刻',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际操作者业务引用',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新操作者',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '沿BaseEntity；事实表禁止删除或软删覆盖',
  `binding_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '绑定号',
  `submission_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '拥有此分配的提交',
  `task_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '任务',
  `binding_revision` bigint NOT NULL COMMENT '绑定版本',
  `source_kind` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'STORE_ORDER或SERVICE_USE',
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '类型化源业务号',
  `source_line_ref` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '稳定源行引用',
  `source_revision` bigint DEFAULT NULL,
  `qty` decimal(18,6) NOT NULL COMMENT '分配数量',
  `uom` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '单位',
  `source_snapshot_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `guard_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源行数量仲裁',
  `admission_kind` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'LEGACY_FUNDED',
  `customer_kind` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `guest_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `identity_revision` bigint DEFAULT NULL,
  `buyer_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `manual_source_revision` bigint DEFAULT NULL,
  `manual_source_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_trade_binding_1` (`tenant_no`,`entity_no`,`binding_no`),
  UNIQUE KEY `uk_bty_trade_binding_2` (`tenant_no`,`entity_no`,`task_no`,`binding_revision`,`source_kind`,`source_no`,`source_line_ref`),
  KEY `idx_bty_trade_binding_1` (`tenant_no`,`entity_no`,`source_kind`,`source_no`,`source_line_ref`),
  CONSTRAINT `ck_bty_trade_binding_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_bty_trade_binding_2` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `ck_bty_trade_binding_3` CHECK ((`qty` > 0)),
  CONSTRAINT `ck_bty_trade_binding_4` CHECK ((`binding_revision` >= 0)),
  CONSTRAINT `ck_bty_trade_binding_5` CHECK ((`source_revision` >= 0)),
  CONSTRAINT `ck_bty_trade_binding_manual_domain` CHECK ((((`admission_kind` = _latin1'LEGACY_FUNDED') and (`source_revision` is not null) and (`source_revision` >= 0) and (`source_snapshot_hash` is not null) and (`manual_source_revision` is null) and (`manual_source_hash` is null) and (`customer_kind` is null) and (`buyer_no` is null) and (`guest_no` is null) and (`identity_revision` is null)) or ((`admission_kind` = _latin1'MANUAL_OFFLINE') and (`customer_kind` is not null) and (((`customer_kind` = _latin1'USER') and (`buyer_no` is not null) and (char_length(`buyer_no`) > 0) and (`guest_no` is null) and ((`identity_revision` is null) or (`identity_revision` > 0))) or ((`customer_kind` = _latin1'GUEST') and (`buyer_no` is null) and (`guest_no` is not null) and (char_length(`guest_no`) > 0) and (`identity_revision` is not null) and (`identity_revision` > 0))) and (`source_revision` is null) and (`source_snapshot_hash` is null) and (`manual_source_revision` is not null) and (`manual_source_revision` > 0) and (`manual_source_hash` is not null) and (char_length(`manual_source_hash`) = 64))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='服务来源行数量分配';

DROP TABLE IF EXISTS `bty_service_submission`;
CREATE TABLE `bty_service_submission` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '物理自增主键，不对外',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT '沿当前租户上下文；不另启租户体系',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '商家主体范围；不等于租户',
  `created_at` datetime(3) NOT NULL COMMENT '创建时刻',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际操作者业务引用',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新操作者',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '沿BaseEntity；事实表禁止删除或软删覆盖',
  `submission_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '提交号',
  `store_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '门店',
  `work_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '工单',
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'OPEN或ADD或BIND等',
  `request_key_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '幂等键摘要',
  `payload_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '参数摘要',
  `status` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'RECEIVED或SOURCE_PENDING或BOUND或RECOVERING或REJECTED',
  `frozen_command` json NOT NULL COMMENT '受控冻结命令',
  `next_retry_at` datetime(3) DEFAULT NULL COMMENT '恢复时刻',
  `failure_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '安全错误码',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_service_submission_1` (`tenant_no`,`entity_no`,`submission_no`),
  UNIQUE KEY `uk_bty_service_submission_2` (`tenant_no`,`entity_no`,`store_no`,`action`,`request_key_hash`),
  KEY `idx_bty_service_submission_1` (`tenant_no`,`entity_no`,`status`,`next_retry_at`),
  CONSTRAINT `ck_bty_service_submission_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_bty_service_submission_2` CHECK ((`deleted` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='业务提交与跨域恢复意图';

DROP TABLE IF EXISTS `bty_reception_operation`;
CREATE TABLE `bty_reception_operation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '物理自增主键，不对外',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT '沿当前租户上下文；不另启租户体系',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '商家主体范围；不等于租户',
  `created_at` datetime(3) NOT NULL COMMENT '创建时刻',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际操作者业务引用',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新操作者',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '沿BaseEntity；事实表禁止删除或软删覆盖',
  `store_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'store_no',
  `operation_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'operation_no',
  `actor_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'actor_no',
  `actor_realm` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'actor_realm',
  `actor_kind` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'actor_kind',
  `endpoint` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'endpoint',
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'action',
  `key_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'key_hash',
  `request_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'request_hash',
  `appointment_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'appointment_no',
  `work_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'work_order_no',
  `identity_kind` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'identity_kind',
  `identity_ref` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'identity_ref',
  `phase` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'phase',
  `appointment_operation_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'appointment_operation_no',
  `derived_key_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'derived_key_hash',
  `frozen_payload` json NOT NULL COMMENT 'frozen_payload',
  `result` json DEFAULT NULL COMMENT 'result',
  `next_retry_at` datetime(3) DEFAULT NULL COMMENT 'next_retry_at',
  `lease_until` datetime(3) DEFAULT NULL COMMENT 'lease_until',
  `failure_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'failure_code',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_reception_operation_1` (`tenant_no`,`entity_no`,`operation_no`),
  UNIQUE KEY `uk_bty_reception_operation_2` (`tenant_no`,`entity_no`,`store_no`,`actor_realm`,`actor_kind`,`actor_no`,`endpoint`,`key_hash`),
  KEY `idx_bty_reception_operation_1` (`tenant_no`,`phase`,`next_retry_at`,`lease_until`,`id`),
  KEY `idx_bty_reception_operation_2` (`tenant_no`,`entity_no`,`store_no`,`appointment_no`),
  KEY `idx_bty_reception_operation_3` (`tenant_no`,`entity_no`,`store_no`,`work_order_no`),
  CONSTRAINT `ck_bty_reception_operation_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_bty_reception_operation_2` CHECK ((`deleted` = 0)),
  CONSTRAINT `ck_bty_reception_operation_3` CHECK ((`phase` in (_utf8mb4'RECEIVED',_utf8mb4'RESOURCE_PENDING',_utf8mb4'ARRIVAL_PENDING',_utf8mb4'OPEN_PENDING',_utf8mb4'SUCCEEDED',_utf8mb4'REJECTED'))),
  CONSTRAINT `ck_bty_reception_operation_4` CHECK ((((`identity_kind` is null) and (`identity_ref` is null)) or ((`identity_kind` in (_utf8mb4'USER',_utf8mb4'GUEST')) and (`identity_ref` is not null) and (char_length(`identity_ref`) > 0)))),
  CONSTRAINT `ck_bty_reception_operation_5` CHECK ((((`identity_kind` is null) and (`identity_ref` is null)) or ((`identity_kind` is not null) and (`identity_kind` in (_latin1'USER',_latin1'GUEST')) and (`identity_ref` is not null) and (char_length(`identity_ref`) > 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

DROP TABLE IF EXISTS `bty_guest_claim_receipt`;
CREATE TABLE `bty_guest_claim_receipt` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '物理自增主键，不对外',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT '沿当前租户上下文；不另启租户体系',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '商家主体范围；不等于租户',
  `created_at` datetime(3) NOT NULL COMMENT '创建时刻',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际操作者业务引用',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新操作者',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '沿BaseEntity；事实表禁止删除或软删覆盖',
  `store_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'store_no',
  `guest_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'guest_no',
  `claim_revision` bigint NOT NULL COMMENT 'claim_revision',
  `user_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'user_no',
  `owner_receipt_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'owner_receipt_hash',
  `recorded_at` datetime(3) NOT NULL COMMENT 'recorded_at',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_guest_claim_receipt_1` (`tenant_no`,`entity_no`,`store_no`,`guest_no`),
  KEY `idx_bty_guest_claim_receipt_1` (`tenant_no`,`entity_no`,`store_no`,`user_no`,`guest_no`),
  CONSTRAINT `ck_bty_guest_claim_receipt_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_bty_guest_claim_receipt_2` CHECK ((`deleted` = 0)),
  CONSTRAINT `ck_bty_guest_claim_receipt_3` CHECK ((`claim_revision` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

DROP TABLE IF EXISTS `bty_arrival_challenge`;
CREATE TABLE `bty_arrival_challenge` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '物理自增主键，不对外',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT '沿当前租户上下文；不另启租户体系',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '商家主体范围；不等于租户',
  `created_at` datetime(3) NOT NULL COMMENT '创建时刻',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际操作者业务引用',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新操作者',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '沿BaseEntity；事实表禁止删除或软删覆盖',
  `store_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'store_no',
  `challenge_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'challenge_no',
  `code` varchar(43) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'code',
  `issued_at` datetime(3) NOT NULL COMMENT 'issued_at',
  `expires_at` datetime(3) NOT NULL COMMENT 'expires_at',
  `actor_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'actor_no',
  `actor_realm` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'actor_realm',
  `actor_kind` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'actor_kind',
  `key_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'key_hash',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_arrival_challenge_1` (`tenant_no`,`entity_no`,`challenge_no`),
  UNIQUE KEY `uk_bty_arrival_challenge_2` (`tenant_no`,`code`),
  UNIQUE KEY `uk_bty_arrival_challenge_3` (`tenant_no`,`entity_no`,`store_no`,`actor_realm`,`actor_kind`,`actor_no`,`key_hash`),
  KEY `idx_bty_arrival_challenge_1` (`tenant_no`,`entity_no`,`store_no`,`expires_at`),
  CONSTRAINT `ck_bty_arrival_challenge_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_bty_arrival_challenge_2` CHECK ((`deleted` = 0)),
  CONSTRAINT `ck_bty_arrival_challenge_3` CHECK ((`expires_at` > `issued_at`)),
  CONSTRAINT `ck_bty_arrival_challenge_4` CHECK ((char_length(`code`) = 43))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

DROP TABLE IF EXISTS `bty_source_observation`;
CREATE TABLE `bty_source_observation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Physical key; never public',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT 'Existing tenant',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Authorized entity',
  `created_at` datetime(3) NOT NULL COMMENT 'Creation time',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Actual actor',
  `updated_at` datetime(3) NOT NULL COMMENT 'Observation update time',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Actual observing actor',
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'Local compare-and-set version',
  `deleted` int NOT NULL DEFAULT '0' COMMENT 'Permanent identity; deletion forbidden',
  `store_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Canonical owner store',
  `source_kind` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'STORE_ORDER only',
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Canonical sub-order number',
  `checkout_caller` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'BEAUTY only',
  `checkout_operation_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Unique owner revision domain',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Canonical ordinary payment root',
  `buyer_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `observation_epoch` bigint NOT NULL DEFAULT '0' COMMENT 'Local monotonic source-call fence',
  `state` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'UNKNOWN or READY or BLOCKED',
  `source_revision` bigint DEFAULT NULL COMMENT 'Highest observed owner revision',
  `source_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Hash paired with highest owner revision',
  `verified_revision` bigint DEFAULT NULL COMMENT 'Last complete verified owner revision',
  `verified_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Hash paired with verified lines',
  `verified_lines` json DEFAULT NULL COMMENT 'Last verified identity and quantity lines; no money',
  `verified_at` datetime(3) DEFAULT NULL COMMENT 'Last complete owner observation time',
  `observed_at` datetime(3) DEFAULT NULL COMMENT 'Current epoch completion time; null while reading',
  `failure_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Safe current blocking reason',
  `admission_kind` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'LEGACY_FUNDED',
  `customer_kind` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `guest_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `identity_revision` bigint DEFAULT NULL,
  `manual_epoch` bigint DEFAULT NULL,
  `manual_state` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `manual_observed_at` datetime(3) DEFAULT NULL,
  `manual_failure_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `manual_revision` bigint DEFAULT NULL,
  `manual_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `manual_verified_revision` bigint DEFAULT NULL,
  `manual_verified_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `manual_verified_lines` json DEFAULT NULL,
  `manual_verified_at` datetime(3) DEFAULT NULL,
  `manual_admission_revision` bigint DEFAULT NULL,
  `manual_admission_state` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_source_observation_1` (`tenant_no`,`entity_no`,`source_kind`,`source_no`),
  UNIQUE KEY `uk_bty_source_observation_2` (`tenant_no`,`entity_no`,`checkout_caller`,`checkout_operation_no`),
  KEY `idx_bty_source_observation_1` (`tenant_no`,`entity_no`,`store_no`,`state`),
  CONSTRAINT `ck_bty_manual_observation_domain` CHECK ((((`admission_kind` = _latin1'LEGACY_FUNDED') and (`buyer_no` is not null) and (`customer_kind` is null) and (`guest_no` is null) and (`identity_revision` is null) and (`manual_epoch` is null) and (`manual_state` is null) and (`manual_observed_at` is null) and (`manual_failure_code` is null) and (`manual_revision` is null) and (`manual_hash` is null) and (`manual_verified_revision` is null) and (`manual_verified_hash` is null) and (`manual_verified_lines` is null) and (`manual_verified_at` is null) and (`manual_admission_revision` is null) and (`manual_admission_state` is null)) or ((`admission_kind` = _latin1'MANUAL_OFFLINE') and (`customer_kind` is not null) and (((`customer_kind` = _latin1'USER') and (`buyer_no` is not null) and (char_length(`buyer_no`) > 0) and (`guest_no` is null) and ((`identity_revision` is null) or (`identity_revision` > 0))) or ((`customer_kind` = _latin1'GUEST') and (`buyer_no` is null) and (`guest_no` is not null) and (char_length(`guest_no`) > 0) and (`identity_revision` is not null) and (`identity_revision` > 0))) and (`manual_epoch` is not null) and (`manual_epoch` > 0) and (`manual_state` is not null) and (`manual_state` in (_latin1'UNKNOWN',_latin1'READY',_latin1'BLOCKED')) and (`state` = _latin1'UNKNOWN') and (`source_revision` is null) and (`source_hash` is null) and (`verified_revision` is null) and (`verified_hash` is null) and (`verified_lines` is null) and (`verified_at` is null)))),
  CONSTRAINT `ck_bty_manual_observation_pair` CHECK ((((`manual_revision` is null) and (`manual_hash` is null)) or ((`manual_revision` is not null) and (`manual_revision` > 0) and (`manual_hash` is not null) and (char_length(`manual_hash`) = 64)))),
  CONSTRAINT `ck_bty_manual_ready` CHECK (((`admission_kind` = _latin1'LEGACY_FUNDED') or ((`manual_state` = _latin1'READY') and (`manual_revision` is not null) and (`manual_verified_revision` is not null) and (`manual_revision` = `manual_verified_revision`) and (`manual_hash` = `manual_verified_hash`) and (`manual_observed_at` is not null) and (`manual_failure_code` is null) and (`manual_admission_revision` is not null) and (`manual_admission_revision` > 0) and (`manual_admission_state` is not null) and (`manual_admission_state` = _latin1'ADMITTED')) or ((`manual_state` in (_latin1'UNKNOWN',_latin1'BLOCKED')) and (`manual_failure_code` is not null) and (char_length(`manual_failure_code`) > 0)))),
  CONSTRAINT `ck_bty_manual_verified_pair` CHECK ((((`manual_verified_revision` is null) and (`manual_verified_hash` is null) and (`manual_verified_lines` is null) and (`manual_verified_at` is null)) or ((`manual_verified_revision` is not null) and (`manual_verified_revision` > 0) and (`manual_verified_hash` is not null) and (char_length(`manual_verified_hash`) = 64) and (`manual_verified_lines` is not null) and (json_type(`manual_verified_lines`) = _latin1'ARRAY') and (json_length(`manual_verified_lines`) > 0) and (json_length(`manual_verified_lines`) <= 20) and (`manual_verified_at` is not null) and (`manual_revision` is not null) and (`manual_verified_revision` <= `manual_revision`) and ((`manual_verified_revision` <> `manual_revision`) or (`manual_verified_hash` = `manual_hash`))))),
  CONSTRAINT `ck_bty_source_observation_1` CHECK (((`version` >= 0) and (`observation_epoch` >= 0))),
  CONSTRAINT `ck_bty_source_observation_2` CHECK ((`deleted` = 0)),
  CONSTRAINT `ck_bty_source_observation_3` CHECK (((`tenant_no` = _utf8mb4'MAIN') and (`source_kind` = _utf8mb4'STORE_ORDER') and (`checkout_caller` = _utf8mb4'BEAUTY'))),
  CONSTRAINT `ck_bty_source_observation_4` CHECK ((`state` in (_utf8mb4'UNKNOWN',_utf8mb4'READY',_utf8mb4'BLOCKED'))),
  CONSTRAINT `ck_bty_source_observation_5` CHECK ((((`source_revision` is null) and (`source_hash` is null)) or ((`source_revision` is not null) and (`source_hash` is not null) and (`source_revision` > 0) and (char_length(`source_hash`) = 64)))),
  CONSTRAINT `ck_bty_source_observation_6` CHECK ((((`verified_revision` is null) and (`verified_hash` is null) and (`verified_lines` is null) and (`verified_at` is null)) or ((`verified_revision` is not null) and (`verified_hash` is not null) and (`verified_lines` is not null) and (`verified_at` is not null) and (`verified_revision` > 0) and (char_length(`verified_hash`) = 64) and (json_type(`verified_lines`) = _utf8mb4'ARRAY') and (json_length(`verified_lines`) > 0) and (json_length(`verified_lines`) <= 20)))),
  CONSTRAINT `ck_bty_source_observation_7` CHECK (((`verified_revision` is null) or ((`source_revision` is not null) and (`verified_revision` <= `source_revision`) and ((`verified_revision` <> `source_revision`) or (`verified_hash` = `source_hash`))))),
  CONSTRAINT `ck_bty_source_observation_8` CHECK ((((`state` = _utf8mb4'READY') and (`observation_epoch` > 0) and (`source_revision` is not null) and (`verified_revision` is not null) and (`source_revision` = `verified_revision`) and (`source_hash` = `verified_hash`) and (`observed_at` is not null) and (`failure_code` is null)) or ((`state` in (_utf8mb4'UNKNOWN',_utf8mb4'BLOCKED')) and (`failure_code` is not null) and (char_length(`failure_code`) > 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

DROP TABLE IF EXISTS `bty_source_allocation_guard`;
CREATE TABLE `bty_source_allocation_guard` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '物理自增主键，不对外',
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN' COMMENT '沿当前租户上下文；不另启租户体系',
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '商家主体范围；不等于租户',
  `created_at` datetime(3) NOT NULL COMMENT '创建时刻',
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '实际操作者业务引用',
  `updated_at` datetime(3) NOT NULL COMMENT '更新时间',
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '更新操作者',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '沿BaseEntity；事实表禁止删除或软删覆盖',
  `guard_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '仲裁号',
  `source_kind` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源类型',
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '来源业务号',
  `source_line_ref` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '稳定来源行',
  `source_revision` bigint DEFAULT NULL,
  `source_qty` decimal(18,6) NOT NULL COMMENT '可信来源数量快照',
  `allocated_qty` decimal(18,6) NOT NULL COMMENT '当前有效分配数量',
  `uom` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '数量单位',
  `source_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `admission_kind` varchar(24) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'LEGACY_FUNDED',
  `customer_kind` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `guest_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `identity_revision` bigint DEFAULT NULL,
  `buyer_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `manual_source_revision` bigint DEFAULT NULL,
  `manual_source_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_bty_source_allocation_guard_1` (`tenant_no`,`entity_no`,`guard_no`),
  UNIQUE KEY `uk_bty_source_allocation_guard_2` (`tenant_no`,`entity_no`,`source_kind`,`source_no`,`source_line_ref`),
  CONSTRAINT `ck_bty_source_allocation_guard_1` CHECK ((`version` >= 0)),
  CONSTRAINT `ck_bty_source_allocation_guard_2` CHECK ((`deleted` in (0,1))),
  CONSTRAINT `ck_bty_source_allocation_guard_3` CHECK ((`source_qty` >= 0)),
  CONSTRAINT `ck_bty_source_allocation_guard_4` CHECK ((`allocated_qty` >= 0)),
  CONSTRAINT `ck_bty_source_allocation_guard_5` CHECK ((`source_revision` >= 0)),
  CONSTRAINT `ck_bty_source_allocation_guard_6` CHECK ((`allocated_qty` <= `source_qty`)),
  CONSTRAINT `ck_bty_source_allocation_guard_manual_domain` CHECK ((((`admission_kind` = _latin1'LEGACY_FUNDED') and (`source_revision` is not null) and (`source_revision` >= 0) and (`source_hash` is not null) and (`manual_source_revision` is null) and (`manual_source_hash` is null) and (`customer_kind` is null) and (`buyer_no` is null) and (`guest_no` is null) and (`identity_revision` is null)) or ((`admission_kind` = _latin1'MANUAL_OFFLINE') and (`customer_kind` is not null) and (((`customer_kind` = _latin1'USER') and (`buyer_no` is not null) and (char_length(`buyer_no`) > 0) and (`guest_no` is null) and ((`identity_revision` is null) or (`identity_revision` > 0))) or ((`customer_kind` = _latin1'GUEST') and (`buyer_no` is null) and (`guest_no` is not null) and (char_length(`guest_no`) > 0) and (`identity_revision` is not null) and (`identity_revision` > 0))) and (`source_revision` is null) and (`source_hash` is null) and (`manual_source_revision` is not null) and (`manual_source_revision` > 0) and (`manual_source_hash` is not null) and (char_length(`manual_source_hash`) = 64))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='来源行服务分配仲裁';

DROP TABLE IF EXISTS `bty_service_execution_fence`;
CREATE TABLE `bty_service_execution_fence` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'MAIN',
  `created_at` datetime(3) NOT NULL,
  `created_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `updated_at` datetime(3) NOT NULL,
  `updated_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `version` bigint NOT NULL DEFAULT '1',
  `deleted` int NOT NULL DEFAULT '0',
  `fence_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `entity_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `store_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `work_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `task_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `binding_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `execution_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `submission_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `definition_version_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `resource_command_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_operation_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_kind` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_line_no` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `binding_revision` bigint NOT NULL,
  `manual_source_revision` bigint NOT NULL,
  `manual_source_epoch` bigint NOT NULL,
  `initial_task_revision` bigint NOT NULL,
  `scope_revision` bigint NOT NULL,
  `unit_ordinal` int NOT NULL,
  `ordered_units` int NOT NULL,
  `attempt_no` int NOT NULL,
  `quantity` int NOT NULL,
  `uom` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'COUNT',
  `manual_source_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_intent_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `binding_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `payload_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `execution_snapshot_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `plan_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `resource_command_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `intent_state` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_fence_revision` bigint NOT NULL DEFAULT '1',
  `observation_epoch` bigint NOT NULL DEFAULT '0',
  `next_retry_at` datetime(3) DEFAULT NULL,
  `observed_grant_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `observed_grant_revision` bigint DEFAULT NULL,
  `observed_grant_state` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
