  `resource_command_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `attempt_no` int NOT NULL,
  `binding_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_intent_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `resource_command_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `plan_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reference_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `lookup_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `retention_no` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `request_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reference_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `lookup_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `route_no` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `route_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `evidence_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `receipt_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `evidence_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `receipt_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `evidence_observed_at` datetime(3) DEFAULT NULL,
  `receipt_observed_at` datetime(3) DEFAULT NULL,
  `observation_state` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `pending_reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `source_fence_revision` bigint NOT NULL,
  `observation_epoch` bigint NOT NULL,
