  UNIQUE KEY `uk_bsesi_task` (`tenant_no`,`entity_no`,`task_no`),
  UNIQUE KEY `uk_bsesi_fence` (`tenant_no`,`fence_no`),
  UNIQUE KEY `uk_bsesi_execution` (`tenant_no`,`execution_no`),
  UNIQUE KEY `uk_bsesi_retention` (`tenant_no`,`retention_no`),
  CONSTRAINT `ck_bsesi_base` CHECK (((`deleted` = 0) and (`version` >= 0) and (`observation_epoch` >= 0) and (`source_fence_revision` > 0) and (`attempt_no` = 1))),
  CONSTRAINT `ck_bsesi_binding_hash` CHECK (regexp_like(`binding_hash`,_latin1'^[a-f0-9]{64}$')),
  CONSTRAINT `ck_bsesi_evidence_hash` CHECK (((`evidence_hash` is null) or regexp_like(`evidence_hash`,_latin1'^[a-f0-9]{64}$'))),
  CONSTRAINT `ck_bsesi_evidence_json` CHECK (((`evidence_json` is null) or json_valid(`evidence_json`))),
  CONSTRAINT `ck_bsesi_evidence_pair` CHECK ((((`evidence_json` is null) and (`evidence_hash` is null) and (`evidence_observed_at` is null)) or ((`evidence_json` is not null) and (`evidence_hash` is not null) and (`evidence_observed_at` is not null)))),
  CONSTRAINT `ck_bsesi_lookup_hash` CHECK (regexp_like(`lookup_hash`,_latin1'^[a-f0-9]{64}$')),
  CONSTRAINT `ck_bsesi_lookup_json` CHECK (json_valid(`lookup_json`)),
  CONSTRAINT `ck_bsesi_lookup_reference_hash` CHECK (((json_extract(`lookup_json`,_latin1'$.reference.referenceHash') is not null) and (json_unquote(json_extract(`lookup_json`,_latin1'$.reference.referenceHash')) = `reference_hash`))),
  CONSTRAINT `ck_bsesi_lookup_request_hash` CHECK (((json_extract(`lookup_json`,_latin1'$.requestHash') is not null) and (json_unquote(json_extract(`lookup_json`,_latin1'$.requestHash')) = `request_hash`))),
  CONSTRAINT `ck_bsesi_lookup_retention_no` CHECK (((json_extract(`lookup_json`,_latin1'$.retentionNo') is not null) and (json_unquote(json_extract(`lookup_json`,_latin1'$.retentionNo')) = `retention_no`))),
  CONSTRAINT `ck_bsesi_plan_hash` CHECK (regexp_like(`plan_hash`,_latin1'^[a-f0-9]{64}$')),
  CONSTRAINT `ck_bsesi_receipt_hash` CHECK (((`receipt_hash` is null) or regexp_like(`receipt_hash`,_latin1'^[a-f0-9]{64}$'))),
  CONSTRAINT `ck_bsesi_receipt_json` CHECK (((`receipt_json` is null) or json_valid(`receipt_json`))),
  CONSTRAINT `ck_bsesi_receipt_pair` CHECK ((((`receipt_json` is null) and (`receipt_hash` is null) and (`receipt_observed_at` is null)) or ((`receipt_json` is not null) and (`receipt_hash` is not null) and (`receipt_observed_at` is not null)))),
  CONSTRAINT `ck_bsesi_ref_attempt_no` CHECK (((json_extract(`reference_json`,_latin1'$.attemptNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.attemptNo')) = `attempt_no`))),
  CONSTRAINT `ck_bsesi_ref_binding_hash` CHECK (((json_extract(`reference_json`,_latin1'$.bindingHash') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.bindingHash')) = `binding_hash`))),
  CONSTRAINT `ck_bsesi_ref_entity_no` CHECK (((json_extract(`reference_json`,_latin1'$.scope.entityNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.scope.entityNo')) = `entity_no`))),
  CONSTRAINT `ck_bsesi_ref_execution_no` CHECK (((json_extract(`reference_json`,_latin1'$.executionNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.executionNo')) = `execution_no`))),
  CONSTRAINT `ck_bsesi_ref_fence_no` CHECK (((json_extract(`reference_json`,_latin1'$.sourceFenceNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.sourceFenceNo')) = `fence_no`))),
  CONSTRAINT `ck_bsesi_ref_plan_hash` CHECK (((json_extract(`reference_json`,_latin1'$.planHash') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.planHash')) = `plan_hash`))),
  CONSTRAINT `ck_bsesi_ref_reference_hash` CHECK (((json_extract(`reference_json`,_latin1'$.referenceHash') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.referenceHash')) = `reference_hash`))),
  CONSTRAINT `ck_bsesi_ref_resource_command_hash` CHECK (((json_extract(`reference_json`,_latin1'$.plannedResourceCommandHash') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.plannedResourceCommandHash')) = `resource_command_hash`))),
  CONSTRAINT `ck_bsesi_ref_resource_command_no` CHECK (((json_extract(`reference_json`,_latin1'$.plannedResourceCommandNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.plannedResourceCommandNo')) = `resource_command_no`))),
  CONSTRAINT `ck_bsesi_ref_source_intent_hash` CHECK (((json_extract(`reference_json`,_latin1'$.sourceIntentHash') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.sourceIntentHash')) = `source_intent_hash`))),
  CONSTRAINT `ck_bsesi_ref_store_no` CHECK (((json_extract(`reference_json`,_latin1'$.scope.storeNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.scope.storeNo')) = `store_no`))),
  CONSTRAINT `ck_bsesi_ref_task_no` CHECK (((json_extract(`reference_json`,_latin1'$.taskNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.taskNo')) = `task_no`))),
  CONSTRAINT `ck_bsesi_ref_tenant_no` CHECK (((json_extract(`reference_json`,_latin1'$.scope.tenantNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.scope.tenantNo')) = `tenant_no`))),
  CONSTRAINT `ck_bsesi_ref_work_order_no` CHECK (((json_extract(`reference_json`,_latin1'$.workOrderNo') is not null) and (json_unquote(json_extract(`reference_json`,_latin1'$.workOrderNo')) = `work_order_no`))),
  CONSTRAINT `ck_bsesi_reference_hash` CHECK (regexp_like(`reference_hash`,_latin1'^[a-f0-9]{64}$')),
  CONSTRAINT `ck_bsesi_reference_json` CHECK (json_valid(`reference_json`)),
  CONSTRAINT `ck_bsesi_request_hash` CHECK (regexp_like(`request_hash`,_latin1'^[a-f0-9]{64}$')),
  CONSTRAINT `ck_bsesi_resource_command_hash` CHECK (regexp_like(`resource_command_hash`,_latin1'^[a-f0-9]{64}$')),
  CONSTRAINT `ck_bsesi_retention_no` CHECK (regexp_like(`retention_no`,_latin1'^[a-f0-9]{64}$')),
  CONSTRAINT `ck_bsesi_route` CHECK ((((`route_no` is null) and (`route_hash` is null)) or ((`route_no` is not null) and (`route_hash` is not null)))),
  CONSTRAINT `ck_bsesi_route_hash` CHECK (((`route_hash` is null) or regexp_like(`route_hash`,_latin1'^[a-f0-9]{64}$'))),
  CONSTRAINT `ck_bsesi_route_no` CHECK (((`route_no` is null) or regexp_like(`route_no`,_latin1'^[a-f0-9]{64}$'))),
